UPDATE game_stack_tower_score
SET max_floor = #{dto.floor},
    perfect_count = COALESCE(#{dto.perfectCount}, 0),
    achieved_at = NOW()
WHERE user_id = #{userId}
  AND (
    max_floor < #{dto.floor}
    OR (max_floor = #{dto.floor} AND perfect_count < COALESCE(#{dto.perfectCount}, 0))
  )
